  uint64_t gsSysInfo::getMemoryInBytes()
  {
#if defined(_WIN32) || defined(_WIN64)

    MEMORYSTATUSEX status;
    status.dwLength = sizeof(status);
    GlobalMemoryStatusEx(&status);
    return (uint64_t)status.ullTotalPhys;

