+
+    void parse(gsExprHelper<Scalar> & evList) const
+    { _u.parse(evList); _v.parse(evList); }
+
+    const gsFeSpace<Scalar> & rowVar() const
+    { return E1::ColBlocks ? _u.rowVar() : _v.rowVar(); }
+    const gsFeSpace<Scalar> & colVar() const
+    {
+        GISMO_ERROR("none");
+    }
