         if (ffv.size() == 2) {
             new_mesh.new_edge(ffv[0],ffv[1]);

         }
         else if (ffv.size() > 2) {
             new_mesh.add_face(ffv);

         }
     }

     // Create of F-faces
     for (auto oldf : faces()) {
         ffv.clear();
         for (auto oldv : vertices(oldf)) {
             ffv.push_back(Map[std::make_pair(oldv, oldf)]);
